    private static void AssertEquivalent(object? expected,object? actual) {
        Assert.Equal(Snapshot(expected),Snapshot(actual));
    }

    private static string Snapshot(object? value) {
        if(value is null) {
            return "<null>";
        }
        if(value is string text) {
            return text;
        }
        if(value is NonGenericEnumerable enumerable) {
            return "["+string.Join(",",SystemEnumerable.Select(SystemEnumerable.Cast<object?>(enumerable),Snapshot))+"]";
        }
        return value.ToString()??string.Empty;
    }
